//! Tool definitions, part 4 of 5: a verbatim slice of the registry table (order is preserved, see `build_registry`).
#![allow(unused_imports)]
use super::*;

pub(super) fn tools(eff_kinds: &[&str]) -> Vec<Command> {
    vec![
    Command { name: "add_mask", description: "Add a mask / selection layer to a clip's mask stack (any number, combined in order by `mode`). kind: rect|ellipse (cx,cy,w,h,rot,round) | path (bezier points [{x,y,ix,iy,ox,oy}] normalized 0..1, in/out tangents are offsets; or ngon {sides,inner,r,cx,cy,rot} for polygon/star) | linear (angle,pos,soft) | radial (cx,cy,r,soft) | luma (lo,hi,soft) | color (r,g,b,tol,soft) | hsl (hue,hue_width,s_lo,s_hi,l_lo,l_hi,soft; optional per-range ramps hue_soft deg 0..180, sat_soft/lum_soft 0..1, default from soft) | difference (ref_clip=clean-plate clip id, tol, soft) | wand (x,y,tol,soft,contiguous) | scribble (fg/bg point lists [[x,y],..]) | edge (thr,soft,thickness) | alpha (thr,soft) | noise (scale,thr,soft,seed,speed). mode: add|subtract|intersect|xor|lighten|darken|difference|none. Every layer has feather (px@720p), expand (px, negative = choke), opacity, invert; all params are keyframable via set_mask_prop_key. Returns mask_id.", mutates: true,
        schema: obj(vec![("clip_id", s("clip")), ("kind", json!({"type":"string","enum":crate::masks::KINDS})), ("mode", json!({"type":"string","enum":crate::masks::MODES})), ("name", s("label")), ("invert", json!({"type":"boolean"})), ("feather", n("px")), ("expand", n("px, negative chokes")), ("opacity", n("0..1")), ("params", json!({"type":"object","description":"kind-specific numeric params"})), ("points", json!({"type":"array","items":{"type":"object"}})), ("closed", json!({"type":"boolean"})), ("ngon", json!({"type":"object"})), ("fg", json!({"type":"array"})), ("bg", json!({"type":"array"})), ("ref_clip", s("clip id for difference matte")), ("interp", json!({"type":"string","enum":["spline","smooth","linear"],"description":"path key interpolation, default spline"}))], &["clip_id","kind"]),
        run: |ss, a| { let kind = str_arg(a, "kind")?.to_string(); if !crate::masks::KINDS.contains(&kind.as_str()) { return Err(format!("bad kind '{kind}', one of {:?}", crate::masks::KINDS)); }
            let id = ss.project.gen_id("mask"); let mut l = crate::masks::new_layer(id.clone(), &kind); apply_layer_args(&mut l, a)?; mask_stack(&mut ss.project, a)?.layers.push(l); Ok(json!({"mask_id": id})) } },
    Command { name: "update_mask", description: "Change a mask layer: mode, invert, enabled, name, feather/expand/opacity, params, points (replaces the path, drops path keys), fg/bg, ref_clip.", mutates: true,
        schema: obj(vec![("clip_id", s("clip")), ("mask_id", s("mask layer id")), ("mode", s("mode")), ("name", s("label")), ("invert", json!({"type":"boolean"})), ("enabled", json!({"type":"boolean"})), ("feather", n("px")), ("expand", n("px")), ("opacity", n("0..1")), ("params", json!({"type":"object"})), ("points", json!({"type":"array","items":{"type":"object"}})), ("closed", json!({"type":"boolean"})), ("ngon", json!({"type":"object"})), ("fg", json!({"type":"array"})), ("bg", json!({"type":"array"})), ("ref_clip", s("clip id"))], &["clip_id","mask_id"]),
        run: |ss, a| { let mid = str_arg(a, "mask_id")?.to_string(); let st = mask_stack(&mut ss.project, a)?; let l = st.layers.iter_mut().find(|l| l.id == mid).ok_or("no such mask")?; apply_layer_args(l, a)?; Ok(json!({"ok":true})) } },
    Command { name: "remove_mask_layer", description: "Delete one mask layer from a clip's stack (remove_mask clears the legacy single mask).", mutates: true,
        schema: obj(vec![("clip_id", s("clip")), ("mask_id", s("mask layer id"))], &["clip_id","mask_id"]),
        run: |ss, a| { let mid = str_arg(a, "mask_id")?.to_string(); let st = mask_stack(&mut ss.project, a)?; let n0 = st.layers.len(); st.layers.retain(|l| l.id != mid); if st.layers.len() == n0 { return Err("no such mask".into()); } Ok(json!({"ok":true})) } },
    Command { name: "reorder_mask", description: "Move a mask layer to a new index in the stack (order matters for add/subtract/intersect).", mutates: true,
        schema: obj(vec![("clip_id", s("clip")), ("mask_id", s("mask layer id")), ("index", n("new index"))], &["clip_id","mask_id","index"]),
        run: |ss, a| { let mid = str_arg(a, "mask_id")?.to_string(); let ix = num_arg(a, "index")? as usize; let st = mask_stack(&mut ss.project, a)?; let pos = st.layers.iter().position(|l| l.id == mid).ok_or("no such mask")?; let l = st.layers.remove(pos); st.layers.insert(ix.min(st.layers.len()), l); Ok(json!({"ok":true})) } },
    Command { name: "list_masks", description: "List a clip's mask stack (ids, kinds, modes, params, key counts) and its track matte.", mutates: false,
        schema: obj(vec![("clip_id", s("clip"))], &["clip_id"]),
        run: |ss, a| { let c = clip(&mut ss.project, a)?; let m = c.mask.as_ref(); Ok(json!({"layers": m.map(|m| m.layers.iter().map(|l| json!({"id": l.id, "kind": l.kind, "mode": l.mode, "invert": l.invert, "enabled": l.enabled, "name": l.name, "points": l.points.len(), "path_keys": l.path_keys.len(), "params": l.props.iter().map(|(k, p)| (k.clone(), json!({"base": p.base, "keys": p.keys.len()}))).collect::<serde_json::Map<_, _>>()})).collect::<Vec<_>>()).unwrap_or_default(), "legacy_shape": m.filter(|m| m.shape != "stack").map(|m| m.shape.clone()), "matte": m.and_then(|m| m.matte.as_ref()).map(|t| json!({"source": t.source, "mode": t.mode, "hide_source": t.hide_source}))})) } },
    Command { name: "set_mask_prop_key", description: "Keyframe any numeric mask layer param at clip-local time (feather, expand, opacity, cx, cy, w, h, rot, round, pos, angle, r, soft, thr, lo, hi, tol, x, y ...). Animated roto, reveals, growing/shrinking selections.", mutates: true,
        schema: obj(vec![("clip_id", s("clip")), ("mask_id", s("mask layer id")), ("property", s("param name")), ("time", n("clip-local seconds")), ("value", n("value")), ("ease", json!({"type":"string","enum":crate::keyframe::EASE_NAMES}))], &["clip_id","mask_id","property","time","value"]),
        run: |ss, a| { let mid = str_arg(a, "mask_id")?.to_string(); let k = str_arg(a, "property")?.to_string(); let (t, v) = (num_arg(a, "time")?, num_arg(a, "value")?); let e: Ease = serde_json::from_value(a.get("ease").cloned().unwrap_or(json!("linear"))).map_err(|e| e.to_string())?;
            let st = mask_stack(&mut ss.project, a)?; let l = st.layers.iter_mut().find(|l| l.id == mid).ok_or("no such mask")?; crate::masks::check_extra(&l.kind, &k, v)?; l.props.entry(k).or_insert(Prop::new(v)).set_key(t, v, e); Ok(json!({"ok":true})) } },
    Command { name: "set_mask_path_key", description: "Keyframe a path mask's whole shape at clip-local time (rotoscoping / animated bezier mask). points: [{x,y,ix,iy,ox,oy}] normalized; point count must match the other keys. Shapes interpolate point by point with smoothstep; hold=true steps.", mutates: true,
        schema: obj(vec![("clip_id", s("clip")), ("mask_id", s("mask layer id")), ("time", n("clip-local seconds")), ("points", json!({"type":"array","items":{"type":"object"}})), ("hold", json!({"type":"boolean"}))], &["clip_id","mask_id","time","points"]),
        run: |ss, a| { let mid = str_arg(a, "mask_id")?.to_string(); let t = num_arg(a, "time")?; let pts = parse_pts(a.get("points").ok_or("missing points")?)?; let hold = a.get("hold").and_then(|v| v.as_bool()).unwrap_or(false);
            let st = mask_stack(&mut ss.project, a)?; let l = st.layers.iter_mut().find(|l| l.id == mid).ok_or("no such mask")?; if l.kind != "path" { return Err("not a path mask".into()); }
            if let Some(k0) = l.path_keys.first() { if k0.points.len() != pts.len() { return Err(format!("point count {} != existing keys {}", pts.len(), k0.points.len())); } }
            l.path_keys.retain(|k| (k.t - t).abs() > 1e-9); l.path_keys.push(crate::masks::PathKey { t, points: pts, hold }); l.path_keys.sort_by(|x, y| x.t.partial_cmp(&y.t).unwrap()); Ok(json!({"keys": l.path_keys.len()})) } },
    Command { name: "roto_propagate", description: "Rotoscope assist: fills in a path mask between your keyframes. You set path keys (set_mask_path_key) on a media clip's path mask at key moments; this tool tracks every outline point frame by frame with dense optical flow forward from each key and backward from the next, blends the two by distance, then snaps the outline to the strongest image edge within snap px along its normal. Writes a path key on every frame between keys (your keys are untouched). Use for neutral or dark occluders that the adaptive occluder cannot cut. Memory is windowed per segment (<=300 frames).", mutates: true,
        schema: obj(vec![("clip_id", s("media clip that carries the path mask")), ("mask_id", s("path mask layer id with >=2 path keys of equal point count")), ("snap", n("edge snap radius in px at project size, default 6, 0 = off")), ("quality", n("flow pyramid levels 2..6, default 4")), ("trust", n("how far the forward and backward flow chains may disagree (fraction of object size) before the result falls back toward plain key interpolation, default 0.12"))], &["clip_id","mask_id"]),
        run: |ss, a| { let mid = str_arg(a, "mask_id")?.to_string(); let cid = str_arg(a, "clip_id")?.to_string();
            let keys = { let st = mask_stack(&mut ss.project, a)?; let l = st.layers.iter().find(|l| l.id == mid).ok_or("no such mask")?; if l.kind != "path" { return Err("not a path mask".into()); } l.path_keys.clone() };
            let (nk, stats) = crate::roto::propagate(&ss.project, &cid, &keys, opt_num(a, "snap", 6.0).clamp(0.0, 40.0), opt_num(a, "quality", 4.0).clamp(2.0, 6.0) as usize, opt_num(a, "trust", 0.12).clamp(0.01, 5.0))?;
            let st = mask_stack(&mut ss.project, a)?; let l = st.layers.iter_mut().find(|l| l.id == mid).ok_or("no such mask")?; l.path_keys = nk; Ok(json!({"keys": l.path_keys.len(), "frames_filled": stats.frames, "segments": stats.segments, "mean_snap_px": stats.mean_snap_px})) } },
    Command { name: "set_track_matte", description: "Track matte: gate this clip by another clip's rendered alpha or luma (inverted variants too). mode alpha|luma|inv_alpha|inv_luma. hide_source hides the matte clip from the output (usual matte workflow). The matte clip is rendered with all its own transforms, effects, masks and animation.", mutates: true,
        schema: obj(vec![("clip_id", s("clip to be matted")), ("matte_clip_id", s("matte source clip")), ("mode", json!({"type":"string","enum":["alpha","luma","inv_alpha","inv_luma"]})), ("hide_source", json!({"type":"boolean"}))], &["clip_id","matte_clip_id"]),
        run: |ss, a| { let src = str_arg(a, "matte_clip_id")?.to_string(); if ss.project.find_clip_mut(&src).is_none() { return Err("no such matte clip".into()); } if src == str_arg(a, "clip_id")? { return Err("a clip cannot matte itself".into()); }
            let mode = a.get("mode").and_then(|v| v.as_str()).unwrap_or("alpha").to_string(); if !["alpha","luma","inv_alpha","inv_luma"].contains(&mode.as_str()) { return Err("bad mode".into()); }
            let hs = a.get("hide_source").and_then(|v| v.as_bool()).unwrap_or(true); mask_stack(&mut ss.project, a)?.matte = Some(crate::masks::Matte { source: src, mode, hide_source: hs }); Ok(json!({"ok":true})) } },
    Command { name: "remove_track_matte", description: "Remove a clip's track matte.", mutates: true,
        schema: obj(vec![("clip_id", s("clip"))], &["clip_id"]),
        run: |ss, a| { mask_stack(&mut ss.project, a)?.matte = None; Ok(json!({"ok":true})) } },
    Command { name: "set_effect_mask", description: "Per-effect mask: an effect only applies where the given mask layer (of the same clip) covers; outside it the clip is untouched. Pass mask_id=\"\" to clear. Use with a luma/color/wand/path layer set to mode none if the layer should not also cut the clip.", mutates: true,
        schema: obj(vec![("clip_id", s("clip")), ("effect_id", s("effect id")), ("mask_id", s("mask layer id or empty"))], &["clip_id","effect_id","mask_id"]),
        run: |ss, a| { let eid = str_arg(a, "effect_id")?.to_string(); let mid = str_arg(a, "mask_id")?.to_string(); let c = clip(&mut ss.project, a)?; if !mid.is_empty() && !c.mask.as_ref().map(|m| m.layers.iter().any(|l| l.id == mid)).unwrap_or(false) { return Err("no such mask layer on this clip".into()); }
            let e = c.effects.iter_mut().find(|e| e.id == eid).ok_or("no such effect")?; if mid.is_empty() { e.strings.remove("mask_layer"); } else { e.strings.insert("mask_layer".into(), mid); } Ok(json!({"ok":true})) } },
    Command { name: "render_mask", description: "Write a mask/selection to a PNG to inspect it: view=matte (white = selected), overlay (red tint over the clip), or cutout (original colour with the matte as alpha: a transparent PNG). mask_id omitted = the whole stack's combined result.", mutates: false,
        schema: obj(vec![("clip_id", s("clip")), ("mask_id", s("one layer, optional")), ("time", n("timeline seconds")), ("path", s("output png")), ("view", json!({"type":"string","enum":["matte","overlay","cutout"]}))], &["clip_id","time","path"]),
        run: |ss, a| { let p = str_arg(a, "path")?.to_string(); let view = a.get("view").and_then(|v| v.as_str()).unwrap_or("matte").to_string(); let mid = a.get("mask_id").and_then(|v| v.as_str()).map(|x| x.to_string()); render::render_mask_png(&ss.project, str_arg(a, "clip_id")?, mid.as_deref(), num_arg(a, "time")?, &view, &p, &mut ss.cache)?; Ok(json!({"path": p})) } },
    Command { name: "set_motion_path", description: "Spatial motion path: the clip travels along a path (After Effects position path / Resolve motion path), added on top of its x/y. Give `points` as through-points [[x,y],..] (normalized 0..1 canvas; with smooth=true they become a smooth curve automatically) or full bezier points [{x,y,ix,iy,ox,oy}], or a `shape` preset (circle, ellipse, figure8, wave, arc, spiral with cx,cy,rx,ry). auto_orient rotates the clip to the tangent (orient_offset deg, orient_smooth 0..1 rounds off corners); constant_speed uses arc length. Progress is the clip property `path` (0..1): pass animate={start,end,ease} to key it over time, or key `path` yourself with set_keyframe (ease, bezier handles and expressions all work, e.g. wiggle).", mutates: true,
        schema: obj(vec![("clip_id", s("clip")), ("points", json!({"type":"array"})), ("shape", json!({"type":"string","enum":["circle","ellipse","figure8","wave","arc","spiral"]})), ("cx", n("preset centre x, default 0.5")), ("cy", n("default 0.5")), ("rx", n("preset radius x, default 0.3")), ("ry", n("default 0.25")), ("smooth", json!({"type":"boolean"})), ("tension", n("0..1, default 1")), ("closed", json!({"type":"boolean"})), ("auto_orient", json!({"type":"boolean"})), ("orient_offset", n("deg")), ("orient_smooth", n("0..1")), ("constant_speed", json!({"type":"boolean"})), ("animate", json!({"type":"object","description":"{start,end,from,to,ease} clip-local seconds and path progress"}))], &["clip_id"]),
        run: |ss, a| { let (pts, closed): (Vec<crate::masks::PathPt>, bool) = if let Some(sh) = a.get("shape").and_then(|v| v.as_str()) { let (p, cl) = crate::motion::preset(sh, opt_num(a, "cx", 0.5), opt_num(a, "cy", 0.5), opt_num(a, "rx", 0.3), opt_num(a, "ry", 0.25)).ok_or("bad shape")?; (crate::motion::smooth_points(&p, cl, opt_num(a, "tension", 1.0)), cl) }
            else if let Some(v) = a.get("points") { let closed = a.get("closed").and_then(|v| v.as_bool()).unwrap_or(false);
                if v.as_array().and_then(|x| x.first()).map(|f| f.is_array()).unwrap_or(false) { let p: Vec<(f64, f64)> = pt_arr(v).into_iter().map(|q| (q[0], q[1])).collect(); if p.len() < 2 { return Err("need at least 2 points".into()); } if a.get("smooth").and_then(|v| v.as_bool()).unwrap_or(true) { (crate::motion::smooth_points(&p, closed, opt_num(a, "tension", 1.0)), closed) } else { (p.iter().map(|q| crate::masks::PathPt { x: q.0, y: q.1, ..Default::default() }).collect(), closed) } }
                else { (parse_pts(v)?, closed) } } else { return Err("give points or shape".into()) };
            if pts.len() < 2 { return Err("need at least 2 points".into()); }
            let mp = crate::motion::MotionPath { points: pts, closed, auto_orient: a.get("auto_orient").and_then(|v| v.as_bool()).unwrap_or(false), orient_offset: opt_num(a, "orient_offset", 0.0), constant_speed: a.get("constant_speed").and_then(|v| v.as_bool()).unwrap_or(true), orient_smooth: opt_num(a, "orient_smooth", 0.0) };
            let c = clip(&mut ss.project, a)?; c.motion_path = Some(mp);
            if let Some(an) = a.get("animate") { let g = |k: &str, d: f64| an.get(k).and_then(|v| v.as_f64()).unwrap_or(d); let e: Ease = serde_json::from_value(an.get("ease").cloned().unwrap_or(json!("in_out"))).map_err(|e| e.to_string())?;
                let (t0, t1) = (g("start", 0.0), g("end", c.duration)); let pr = c.props.entry("path".to_string()).or_insert(Prop::new(0.0)); pr.set_key(t0, g("from", 0.0), e.clone()); pr.set_key(t1, g("to", 1.0), e); }
            Ok(json!({"ok":true})) } },
    Command { name: "remove_motion_path", description: "Remove a clip's motion path.", mutates: true,
        schema: obj(vec![("clip_id", s("clip"))], &["clip_id"]),
        run: |ss, a| { let c = clip(&mut ss.project, a)?; c.motion_path = None; c.props.remove("path"); Ok(json!({"ok":true})) } },
    Command { name: "set_flow_blur", description: "Optical-flow motion blur for footage (AE Pixel Motion Blur / Resolve Motion Blur): estimates dense flow between this frame and the next and smears each pixel along its own motion. amount = shutter as a fraction of a frame (0.5 = 180 degrees), quality = pyramid levels 3-6. amount 0 turns it off. Works on media clips; keyframe `flow_blur` with set_keyframe to animate. Gaps: forward flow only, no occlusion handling (halos at object edges), CPU (about 0.3-0.6 s per 720p frame).", mutates: true,
        schema: obj(vec![("clip_id", s("media clip")), ("amount", n("0..2, 0.5 = 180 degree shutter")), ("quality", n("3..6, default 4"))], &["clip_id","amount"]),
        run: |ss, a| { let amt = num_arg(a, "amount")?.clamp(0.0, 2.0); let q = opt_num(a, "quality", 4.0).clamp(3.0, 6.0); let c = clip(&mut ss.project, a)?; if !matches!(c.source, Source::Media { .. }) { return Err("flow blur needs a media clip".into()); }
            c.props.insert("flow_blur".into(), Prop::new(amt)); c.props.insert("flow_quality".into(), Prop::new(q)); Ok(json!({"ok":true})) } },
    Command { name: "render_flow", description: "Write a colour-wheel picture of the optical flow between a media clip's frame at `time` and the next frame (hue = direction, brightness = speed). Returns seconds taken. For inspecting motion.", mutates: false,
        schema: obj(vec![("clip_id", s("media clip")), ("time", n("timeline seconds")), ("path", s("output png"))], &["clip_id","time","path"]),
        run: |ss, a| { let p = str_arg(a, "path")?.to_string(); let secs = render::render_flow_png(&ss.project, str_arg(a, "clip_id")?, num_arg(a, "time")?, &p, &mut ss.cache)?; Ok(json!({"path": p, "flow_seconds": secs})) } },
    Command { name: "track_planar", description: "Planar (homography) tracker, mocha-style. Tracks a flat surface's 4 corners (TL,TR,BR,BL, normalized 0..1 at frame `start`) through a media clip and, when target_clip_id is given, pins that layer onto the surface with perspective (the target's whole canvas maps to the tracked quad, so lay text out inside the canvas where the quad is). Photometric-invariant (exposure/flicker), robust to occluders (Tukey weights), drift-free (re-aligns to the frame-0 template every frame), coasts through full occlusion and re-acquires. light=0..1 matches the surface's brightness changes on the layer. Set motion_blur on the target to blur the pinned layer along its tracked motion. Returns per-frame confidence summary and lost frames.", mutates: true,
        schema: obj(vec![("clip_id", s("media clip to track")), ("reanchor", json!({"type":"boolean","description":"segment mode: refresh the template when the original no longer matches but the frame-to-frame fit is confident (lighting or appearance change); default false"})), ("corners", json!({"type":"array","items":{"type":"number"},"description":"8 numbers x0,y0,x1,y1,x2,y2,x3,y3 normalized, TL TR BR BL"})), ("target_clip_id", s("layer to pin")), ("expand", n("pin margin: the target canvas covers the tracked plane extended by this fraction on every side (0 = canvas is exactly the plane; 0.5 leaves room for things such as shards to fly past the plane edge). Lay content out in the central 1/(1+2*expand) of the canvas.")), ("start", n("first frame index in the clip, default 0")), ("end", n("last frame index, default end")), ("levels", n("pyramid levels 2-5, default 3")), ("light", n("0..1 brightness match, default 0")), ("return_quads", json!({"type":"boolean"})), ("context_corners", json!({"type":"array","items":{"type":"number"},"description":"8 numbers, normalized TL TR BR BL: a larger, well-textured plane that contains or sits rigidly with the target (e.g. the whole keyboard around one key). It is tracked instead of `corners`, and the `corners` quad is carried along by the context plane homography. Survives occluders over the target; follows camera/plane motion only, not the target's own deformation or press."})), ("scale_damp", n("0..1, default 0. With shape_lock active, damps per-step uniform scale change so the quad cannot drift smaller while the plane is covered (0.9 = near-constant scale; leave 0 for real zooms/dollies)")), ("shape_lock", n("0..1, default 0. Floor on the rigid+scale constraint: 1 forbids shear/perspective/aspect change entirely (use for occluded, low-texture or blurred planes where the free homography shrinks into the visible part); 0 = free homography unless occlusion is detected")), ("occluder_matte", json!({"type":"boolean","description":"cut the pinned layer wherever something covers the tracked surface (compares the live frame to the frame-0 surface; session-only anchor, redo after reload)"})), ("occluder_mode", json!({"type":"string","enum":["anchor","adaptive"],"description":"anchor (default): compare to the frame-0 surface. adaptive: keep a running model of the visible surface in plane space, so key presses, focus and lighting change on the surface are absorbed and only fast-appearing things (a finger) are cut. Follows the clip speed (the model update rate is per unit of source time, not per displayed frame). Computed once per target (streaming, plane resolution) and cached."})), ("occluder_expand", n("0..2, default 0 (off). Adaptive mode: extend the matte plane beyond the tracked quad by this fraction of the quad size on every side (planar extrapolation), so occluders over the surroundings are also matted. Needed when the matte feeds something that leaves the quad (shard_burst plane.occlusion_target). Assumes the surroundings lie roughly in the tracked plane. The image-space matte outside the extended rectangle is fully visible.")),("occluder_luma_gate", n("0..2, default 0 (off). 1 = two-sided luma term, 2 = brighter-than-surface only (use when the occluder is lighter than the surface, e.g. a finger over a dark key; the two-sided term made false rejects on real footage). Adaptive mode with occluder_chroma > 0: adds a gated luma term (weight = gate, with a 0.12 dead zone so glyph edge shading does not count) next to the chroma metric, aimed at neutral or dark occluders that chroma alone cannot cut. Pair with occluder_min_area / occluder_thin so luma false positives on small printed glyphs are removed. Experimental: mode 1 false-rejected 1.7-6.2% of a clear patch on real monochrome footage; mode 2 0% there and 0%/0% on the synthetic fixture, but real finger crossings are unproven.")),("occluder_close", n("0..8 plane px, default 0 (off). Adaptive mode: grey morphological closing of the occluder matte (after the island cleanup), which fills small notches and bays touching the occluder edge and smooths edge scallops. 2-3 typical; larger radii also bridge real gaps between occluder parts.")),("occluder_thin", n("0..6 plane px, default 0 (off). Adaptive mode: with occluder_min_area > 0, also drops enclosed occluder structures (not touching the plane border, up to 40x min_area) whose mean half-thickness is below this, i.e. thin contour/outline residue of printed glyphs, without raising min_area enough to eat small real parts. 1.5-2.5 typical.")),("occluder_temporal", n("0..3, default 0 (off). Adaptive mode: temporal median of the occluder matte over +-N neighbouring output frames, which removes single-frame flashes (a wrong amber band or a sudden exposed hole for one frame). 1 = median of 3, 2 = median of 5. Costs one frame of response lag on genuinely fast edges.")),("occluder_min_area", n("0..0.2, default 0 (off). Adaptive mode: occluder islands and visible holes smaller than this fraction of the tracked plane area are removed, so isolated glyph/speckle false positives do not punch holes in the pinned layer and small gaps inside a finger are filled. 0.003-0.01 is typical.")), ("occluder_tolerance", n("0..8 plane pixels (256 px across the tracked quad), default 1. Adaptive mode: how far the surface may shift against the tracked plane (key press, parallax) before a pixel counts as an occluder. Compares against the min/max envelope of the surface model within this radius.")), ("occluder_chroma", n("0..1, default 0. Weight of the chroma-only comparison in the occluder matte: 1 ignores brightness/focus/glyph changes on a neutral surface and only cuts coloured occluders such as skin or cloth; 0 = classic luminance-dominated difference")), ("occluder_softness", n("0.3-3, higher = more sensitive, default 1"))], &["clip_id","corners"]),
        run: |ss, a| { let cid = str_arg(a, "clip_id")?.to_string(); let cr: Vec<f64> = a.get("corners").and_then(|v| v.as_array()).ok_or("corners needed")?.iter().filter_map(|v| v.as_f64()).collect(); if cr.len() != 8 { return Err("corners needs 8 numbers".into()); }
            let (w, h) = (ss.project.width as f64, ss.project.height as f64); let mut q = [[0f64; 2]; 4]; for i in 0..4 { q[i] = [cr[i * 2] * w, cr[i * 2 + 1] * h]; }
            let mc = ss.project.find_clip(&cid).ok_or("no such clip")?.clone(); let nf = ((mc.duration * ss.project.fps).ceil() as usize).max(1); let f0 = opt_num(a, "start", 0.0) as usize; let f1 = (opt_num(a, "end", (nf - 1) as f64) as usize).min(nf - 1);
            let t0 = std::time::Instant::now(); crate::planar::SCALE_DAMP.store((opt_num(a, "scale_damp", 0.0).clamp(0.0, 1.0) as f32).to_bits(), std::sync::atomic::Ordering::Relaxed); crate::planar::SHAPE_LOCK.store((opt_num(a, "shape_lock", 0.0).clamp(0.0, 1.0) as f32).to_bits(), std::sync::atomic::Ordering::Relaxed); let ctx: Option<[[f64; 2]; 4]> = a.get("context_corners").and_then(|v| v.as_array()).and_then(|v| { let c: Vec<f64> = v.iter().filter_map(|x| x.as_f64()).collect(); if c.len() == 8 { Some([[c[0] * w, c[1] * h], [c[2] * w, c[3] * h], [c[4] * w, c[5] * h], [c[6] * w, c[7] * h]]) } else { None } }); let tr_r = crate::planar::track_opts(&ss.project, &cid, ctx.unwrap_or(q), f0, f1, opt_num(a, "levels", 3.0) as usize, a.get("reanchor").and_then(|v| v.as_bool()).unwrap_or(false)); crate::planar::SHAPE_LOCK.store(0, std::sync::atomic::Ordering::Relaxed); crate::planar::SCALE_DAMP.store(0, std::sync::atomic::Ordering::Relaxed); let mut tr = tr_r?; if let Some(cq) = ctx { for qd in tr.quads.iter_mut() { if let Some(o) = crate::planar::propagate_quad(&cq, qd, &q) { *qd = o; } } } let secs = t0.elapsed().as_secs_f64();
            if let Some(tid) = a.get("target_clip_id").and_then(|v| v.as_str()) { let fps = ss.project.fps; let ts = ss.project.find_clip(tid).ok_or("no target clip")?.start; let light = opt_num(a, "light", 0.0);
                let tc = ss.project.find_clip_mut(tid).ok_or("no target clip")?; tc.props.insert("pin_on".into(), Prop::new(1.0)); tc.props.insert("pin_light".into(), Prop::new(light));
                let ex = opt_num(a, "expand", 0.0).clamp(0.0, 2.0); let pq: Vec<[[f64; 2]; 4]> = tr.quads.iter().map(|qd| if ex <= 0.0 { *qd } else { let m = crate::shards::sq2quad([(qd[0][0], qd[0][1]), (qd[1][0], qd[1][1]), (qd[2][0], qd[2][1]), (qd[3][0], qd[3][1])]); let e = |u: f64, v: f64| { let (x, y) = crate::shards::hmap(&m, u, v); [x, y] }; [e(-ex, -ex), e(1.0 + ex, -ex), e(1.0 + ex, 1.0 + ex), e(-ex, 1.0 + ex)] }).collect();
                for k in 0..4 { for (ax, nm) in [(0usize, "x"), (1, "y")] { let mut pr = Prop::new(pq[0][k][ax]); for (i, qd) in pq.iter().enumerate() { pr.set_key(mc.start + (f0 + i) as f64 / fps - ts, qd[k][ax], Ease::Linear); } tc.props.insert(format!("pin{k}{nm}"), pr); } }
                let mut g = Prop::new(1.0); for (i, v) in tr.gain.iter().enumerate() { g.set_key(mc.start + (f0 + i) as f64 / fps - ts, *v, Ease::Linear); } tc.props.insert("pin_gain".into(), g); }
            if a.get("target_clip_id").is_some() && a.get("occluder_matte").and_then(|v| v.as_bool()).unwrap_or(false) { let tid = str_arg(a, "target_clip_id")?.to_string(); crate::render::prepare_at(&ss.project, &mut ss.cache, Some(mc.start + f0 as f64 / ss.project.fps + 1e-4))?;
                if let Some(fr) = ss.cache.frames_of(&cid) { if let Some(b) = fr.get(if mc.speed_curve.is_some() { mc.source_index(f0 as f64 / ss.project.fps, ss.project.fps) } else { f0 }) { if let crate::model::Source::Media { asset } = &mc.source { if let Some(asset_rec) = ss.project.assets.get(asset) { ss.project.occluders.insert(tid.clone(), crate::model::OccSpec { src: cid.clone(), src_start: mc.start, path: asset_rec.path.clone(), src_time: if mc.speed_curve.is_some() { mc.in_point } else { mc.in_point + f0 as f64 / ss.project.fps * mc.speed }, q0: q, soft: opt_num(a, "occluder_softness", 1.0) as f32, chroma: opt_num(a, "occluder_chroma", 0.0).clamp(0.0, 1.0) as f32, w: ss.project.width as usize, h: ss.project.height as usize, adaptive: a.get("occluder_mode").and_then(|v| v.as_str()) == Some("adaptive"), f0, speed: mc.speed.max(0.01), tol: opt_num(a, "occluder_tolerance", 1.0).clamp(0.0, 8.0) as f32, min_area: opt_num(a, "occluder_min_area", 0.0).clamp(0.0, 0.2) as f32, temporal: opt_num(a, "occluder_temporal", 0.0).clamp(0.0, 3.0).round() as usize, thin: opt_num(a, "occluder_thin", 0.0).clamp(0.0, 6.0) as f32, close: opt_num(a, "occluder_close", 0.0).clamp(0.0, 8.0) as f32, ramp: if mc.speed_curve.is_some() { let fpsv = ss.project.fps; (0..=((mc.duration * fpsv).ceil() as usize).min(4000)).map(|k| mc.source_time(k as f64 / fpsv)).collect() } else { vec![] }, lgate: opt_num(a, "occluder_luma_gate", 0.0).clamp(0.0, 2.0) as f32, expand: opt_num(a, "occluder_expand", 0.0).clamp(0.0, 2.0) as f32 }); crate::planar::clear_seq(&tid); } } crate::planar::set_anchor(&tid, crate::planar::Anchor { src: cid.clone(), src_start: mc.start, frame: b.to_vec(), q0: q, w: ss.project.width as usize, h: ss.project.height as usize, soft: opt_num(a, "occluder_softness", 1.0) as f32, chroma: opt_num(a, "occluder_chroma", 0.0).clamp(0.0, 1.0) as f32 }); } } }
            let lostf: Vec<usize> = tr.lost.iter().enumerate().filter(|(_, l)| **l).map(|(i, _)| f0 + i).collect(); let mean = tr.conf.iter().sum::<f64>() / tr.conf.len() as f64; let minc = tr.conf.iter().cloned().fold(1.0, f64::min);
            let mut res = json!({"frames": tr.quads.len(), "seconds": secs, "mean_conf": mean, "min_conf": minc, "lost_frames": lostf.len(), "lost_ranges": lostf.first().map(|f| vec![*f, *lostf.last().unwrap()])});
            if a.get("return_quads").and_then(|v| v.as_bool()).unwrap_or(false) { res["quads"] = json!(tr.quads.iter().map(|q| q.iter().flat_map(|p| vec![p[0], p[1]]).collect::<Vec<f64>>()).collect::<Vec<_>>()); res["conf"] = json!(tr.conf); }
            Ok(res) } },
    Command { name: "pin_layer", description: "Manually pin a layer's whole canvas onto a quad (pixel coords TL,TR,BR,BL) at `time` (clip-local seconds), keyframed, perspective-correct, anti-aliased. Use for hand-keyed corner pins; track_planar writes the same keys automatically. quad omitted + off=true removes the pin.", mutates: true,
        schema: obj(vec![("clip_id", s("layer")), ("time", n("clip-local seconds")), ("quad", json!({"type":"array","items":{"type":"number"},"description":"8 numbers px"})), ("keys", json!({"type":"array","items":{"type":"object"},"description":"batch: [{time, quad}] many keys in one call"})), ("off", json!({"type":"boolean"}))], &["clip_id"]),
        run: |ss, a| { let c = clip(&mut ss.project, a)?; if a.get("off").and_then(|v| v.as_bool()).unwrap_or(false) { c.props.remove("pin_on"); return Ok(json!({"ok":true})); }
            let mut list: Vec<(f64, Vec<f64>)> = vec![]; if let Some(ks) = a.get("keys").and_then(|v| v.as_array()) { for k in ks { let t = k.get("time").and_then(|v| v.as_f64()).ok_or("key needs time")?; let q: Vec<f64> = k.get("quad").and_then(|v| v.as_array()).ok_or("key needs quad")?.iter().filter_map(|v| v.as_f64()).collect(); list.push((t, q)); } }
            else { let q: Vec<f64> = a.get("quad").and_then(|v| v.as_array()).ok_or("quad needed")?.iter().filter_map(|v| v.as_f64()).collect(); list.push((opt_num(a, "time", 0.0), q)); }
            if list.iter().any(|(_, q)| q.len() != 8) { return Err("quad needs 8 numbers".into()); }
            c.props.insert("pin_on".into(), Prop::new(1.0)); for (t, q) in &list { for k in 0..4 { for (ax, nm) in [(0usize, "x"), (1, "y")] { let key = format!("pin{k}{nm}"); let pr = c.props.entry(key).or_insert_with(|| Prop::new(q[k * 2 + ax])); pr.set_key(*t, q[k * 2 + ax], Ease::Linear); } } } Ok(json!({"ok":true,"keys":list.len()})) } },
    Command { name: "get_curve", description: "Graph editor read: all keyframes of a clip property (time, value, ease, bezier handles) plus optional dense samples of value and SPEED (units per second) for the speed graph. samples=N evaluates N points across [t0,t1] (default the key range).", mutates: false,
        schema: obj(vec![("clip_id", s("clip")), ("property", s("property name, e.g. x, scale, opacity, pin0x")), ("samples", n("0..500")), ("t0", n("")), ("t1", n(""))], &["clip_id","property"]),
        run: |ss, a| { let c = ss.project.find_clip(str_arg(a, "clip_id")?).ok_or("no such clip")?; let pr = c.props.get(str_arg(a, "property")?).ok_or("no such property")?;
            let keys: Vec<Value> = pr.keys.iter().map(|k| { let mut o = json!({"time":k.t,"value":k.v,"ease":format!("{:?}",k.ease).to_lowercase(),"bezier":k.bez}); if let Some(h) = k.out { o["out"] = json!({"dt": h.dt, "dv": h.dv}); } if let Some(h) = k.inn { o["in"] = json!({"dt": h.dt, "dv": h.dv}); } o }).collect(); let mut o = json!({"base":pr.base,"keys":keys,"expressions":pr.expr.len()});
            let ns = opt_num(a, "samples", 0.0).clamp(0.0, 500.0) as usize; if ns >= 2 { let t0 = opt_num(a, "t0", pr.keys.first().map(|k| k.t).unwrap_or(0.0)); let t1 = opt_num(a, "t1", pr.keys.last().map(|k| k.t).unwrap_or(c.duration)); let dt = (t1 - t0) / (ns - 1) as f64;
                let ts: Vec<f64> = (0..ns).map(|i| t0 + dt * i as f64).collect(); let vs: Vec<f64> = ts.iter().map(|&t| pr.at(t)).collect(); let sp: Vec<f64> = ts.iter().map(|&t| (pr.at(t + 1e-3) - pr.at(t - 1e-3)) / 2e-3).collect(); o["t"] = json!(ts); o["value"] = json!(vs); o["speed"] = json!(sp); }
            Ok(o) } },
    Command { name: "move_key", description: "Graph editor: move a keyframe in time and/or change its value. Identify it by its current `time` (nearest key within 1/2 frame). new_time and new_value optional.", mutates: true,
        schema: obj(vec![("clip_id", s("clip")), ("property", s("property")), ("time", n("current key time")), ("new_time", n("")), ("new_value", n(""))], &["clip_id","property","time"]),
        run: |ss, a| { let t = num_arg(a, "time")?; let fps = ss.project.fps; let c = clip(&mut ss.project, a)?; let pr = c.props.get_mut(str_arg(a, "property")?).ok_or("no such property")?;
            let i = pr.keys.iter().enumerate().min_by(|x, y| (x.1.t - t).abs().partial_cmp(&(y.1.t - t).abs()).unwrap()).filter(|(_, k)| (k.t - t).abs() <= 0.5 / fps).map(|(i, _)| i).ok_or("no key at that time")?;
            if let Some(v) = a.get("new_value").and_then(|v| v.as_f64()) { pr.keys[i].v = v; } if let Some(nt) = a.get("new_time").and_then(|v| v.as_f64()) { pr.keys[i].t = nt; pr.keys.sort_by(|x, y| x.t.partial_cmp(&y.t).unwrap()); } Ok(json!({"ok":true,"keys":pr.keys.len()})) } },
    Command { name: "remove_key", description: "Graph editor: delete the keyframe nearest `time` (within half a frame).", mutates: true,
        schema: obj(vec![("clip_id", s("clip")), ("property", s("property")), ("time", n("key time"))], &["clip_id","property","time"]),
        run: |ss, a| { let t = num_arg(a, "time")?; let fps = ss.project.fps; let c = clip(&mut ss.project, a)?; let pr = c.props.get_mut(str_arg(a, "property")?).ok_or("no such property")?; let n0 = pr.keys.len(); pr.keys.retain(|k| (k.t - t).abs() > 0.5 / fps); if pr.keys.len() == n0 { return Err("no key at that time".into()); } Ok(json!({"ok":true,"keys":pr.keys.len()})) } },
    Command { name: "copy_curve", description: "Graph editor copy/paste: copy a property's keyframes onto another clip/property with optional time offset, time scale, value scale/offset, reverse, invert. Replaces the destination keys.", mutates: true,
        schema: obj(vec![("from_clip", s("source clip")), ("from_property", s("")), ("to_clip", s("destination clip")), ("to_property", s("")), ("time_offset", n("seconds added")), ("time_scale", n("default 1")), ("value_scale", n("default 1")), ("value_offset", n("default 0")), ("reverse", json!({"type":"boolean"})), ("invert", json!({"type":"boolean"}))], &["from_clip","from_property","to_clip","to_property"]),
        run: |ss, a| { let src = ss.project.find_clip(str_arg(a, "from_clip")?).ok_or("no source clip")?.props.get(str_arg(a, "from_property")?).ok_or("no source property")?.clone(); let (to, tp) = (str_arg(a, "to_clip")?.to_string(), str_arg(a, "to_property")?.to_string());
            let (to_off, ts, vs, vo) = (opt_num(a, "time_offset", 0.0), opt_num(a, "time_scale", 1.0), opt_num(a, "value_scale", 1.0), opt_num(a, "value_offset", 0.0)); let rev = a.get("reverse").and_then(|v| v.as_bool()).unwrap_or(false); let inv = a.get("invert").and_then(|v| v.as_bool()).unwrap_or(false);
            let tc = ss.project.find_clip_mut(&to).ok_or("no destination clip")?; let mut np = src.clone(); let tmax = src.keys.last().map(|k| k.t).unwrap_or(0.0);
            for k in np.keys.iter_mut() { if rev { k.t = tmax - k.t; } k.t = k.t * ts + to_off; k.v = (if inv { -k.v } else { k.v }) * vs + vo; } np.keys.sort_by(|x, y| x.t.partial_cmp(&y.t).unwrap()); np.base = (if inv { -src.base } else { src.base }) * vs + vo; let n = np.keys.len(); tc.props.insert(tp, np); Ok(json!({"ok":true,"keys":n})) } },
    Command { name: "simplify_curve", description: "Graph editor: reduce a dense keyframe curve (e.g. a per-frame tracker output) to the fewest keys that stay within `tolerance` (value units) of the original (Ramer-Douglas-Peucker on the evaluated curve). Returns before/after key counts and the max error.", mutates: true,
        schema: obj(vec![("clip_id", s("clip")), ("property", s("property")), ("tolerance", n("max error in value units, default 0.25"))], &["clip_id","property"]),
        run: |ss, a| { let tol = opt_num(a, "tolerance", 0.25); let c = clip(&mut ss.project, a)?; let pr = c.props.get_mut(str_arg(a, "property")?).ok_or("no such property")?; let orig = pr.clone(); let n = pr.keys.len(); if n < 3 { return Ok(json!({"before":n,"after":n,"max_error":0.0})); }
            let mut keep = vec![false; n]; keep[0] = true; keep[n - 1] = true; let mut st = vec![(0usize, n - 1)];
            while let Some((i, j)) = st.pop() { let (a0, b0) = (&orig.keys[i], &orig.keys[j]); let (mut md, mut mi) = (-1.0f64, i); for k in i + 1..j { let u = (orig.keys[k].t - a0.t) / (b0.t - a0.t).max(1e-9); let d = (orig.keys[k].v - (a0.v + (b0.v - a0.v) * u)).abs(); if d > md { md = d; mi = k; } } if md > tol { keep[mi] = true; st.push((i, mi)); st.push((mi, j)); } }
            let mut i = 0; pr.keys.retain(|_| { let k = keep[i]; i += 1; k }); let mut me = 0f64; for k in &orig.keys { me = me.max((pr.at(k.t) - k.v).abs()); } Ok(json!({"before":n,"after":pr.keys.len(),"max_error":me})) } },
    ]
}
